class Solution {
public:
    vector<int> sortEvenOdd(vector<int>& nums) {
        vector<int> even, odd;
        for (int i = 0; i < (int)nums.size(); ++i)
            (i % 2 ? odd : even).push_back(nums[i]);
        sort(even.begin(), even.end());
        sort(odd.rbegin(), odd.rend());
        for (int i = 0, k = 0; i < (int)nums.size(); i += 2) nums[i] = even[k++];
        for (int i = 1, k = 0; i < (int)nums.size(); i += 2) nums[i] = odd[k++];
        return nums;
    }
};

