class Solution {
    public int[] sortEvenOdd(int[] nums) {
        int n = nums.length;
        int[] even = new int[(n + 1) / 2];
        Integer[] odd = new Integer[n / 2];
        for (int i = 0, e = 0, o = 0; i < n; i++) {
            if (i % 2 == 0) even[e++] = nums[i];
            else odd[o++] = nums[i];
        }
        Arrays.sort(even);
        Arrays.sort(odd, Collections.reverseOrder());
        for (int i = 0, k = 0; i < n; i += 2) nums[i] = even[k++];
        for (int i = 1, k = 0; i < n; i += 2) nums[i] = odd[k++];
        return nums;
    }
};

