    const even = nums.filter((_, i) => i % 2 === 0).sort((a, b) => a - b);
    const odd = nums.filter((_, i) => i % 2 === 1).sort((a, b) => b - a);
    for (let i = 0, e = 0, o = 0; i < nums.length; i++)
        nums[i] = i % 2 === 0 ? even[e++] : odd[o++];
    return nums;
};

