    def sortEvenOdd(self, nums: List[int]) -> List[int]:
        cnt = [[0] * 101, [0] * 101]
        for i, x in enumerate(nums):
            cnt[i & 1][x] += 1
        res = []
        e, o = 0, 100
        for i in range(len(nums)):
            if i % 2 == 0:
                while cnt[0][e] == 0:
                    e += 1
                res.append(e)
                cnt[0][e] -= 1
            else:
                while cnt[1][o] == 0:
                    o -= 1
                res.append(o)
                cnt[1][o] -= 1
        return res

