class Solution {
public:
    vector<int> sortEvenOdd(vector<int>& nums) {
        int cnt[2][101] = {};
        for (int i = 0; i < (int)nums.size(); ++i) cnt[i & 1][nums[i]]++;
        vector<int> res;
        res.reserve(nums.size());
        int e = 0, o = 100;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if ((i & 1) == 0) {
                while (cnt[0][e] == 0) ++e;
                res.push_back(e);
                --cnt[0][e];
            } else {
                while (cnt[1][o] == 0) --o;
                res.push_back(o);
                --cnt[1][o];
            }
        }
        return res;
    }
};

