class Solution {
    public int[] sortEvenOdd(int[] nums) {
        int[][] cnt = new int[2][101];
        for (int i = 0; i < nums.length; i++) cnt[i & 1][nums[i]]++;
        int[] res = new int[nums.length];
        int e = 0, o = 100;
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) {
                while (cnt[0][e] == 0) e++;
                res[i] = e;
                cnt[0][e]--;
            } else {
                while (cnt[1][o] == 0) o--;
                res[i] = o;
                cnt[1][o]--;
            }
        }
        return res;
    }
};

